    if not isinstance(text, str):
        raise TypeError("Input must be a string")

    valid_chars = set('abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ')
    vowels = set('aeiouAEIOU')

