def reverse_words_preserving_spacing(s: str) -> str:
    n = len(s)
    if n == 0:
        return s

    words = []
    spaces = []

    i = 0
    while i < n:
        if s[i] == ' ':
            space_count = 0
            while i < n and s[i] == ' ':
                space_count += 1
                i += 1
            spaces.append(space_count)
        else:
            word_start = i
            while i < n and s[i] != ' ':
                i += 1
            words.append(s[word_start:i])

    if not words:
        return s

    words.reverse()
    spaces.reverse()

    result = []
