class StringProcessor:
    @staticmethod
    def reverse_words(text):
        if not text:
            return text
        start = 0
        end = len(text) - 1
        chars = list(text)
        while start < end and chars[start] == ' ':
            start += 1
        while end > start and chars[end] == ' ':
            end -= 1
        if start > end:
            return ''
        word_start = start
        word_end = start
        while word_end <= end:
            if chars[word_end] == ' ' or word_end == end:
                if word_end == end and chars[word_end] != ' ':
                    temp_end = word_end
                else:
                    temp_end = word_end - 1
                left = word_start
                right = temp_end
                while left < right:
                    chars[left], chars[right] = chars[right], chars[left]
                    left += 1
                    right -= 1
                word_start = word_end + 1
            word_end += 1
        left = start
        right = end
        while left < right:
            chars[left], chars[right] = chars[right], chars[left]
            left += 1
            right -= 1
        return ''.join(chars)

