import collections

def reverse_words(text):
    if not isinstance(text, str):
        raise TypeError("Input must be a string")

    words = text.split()

    if not words:
        return ""

    deque = collections.deque(words)

    result_parts = []
    while deque:
        result_parts.append(deque.popleft())

    return " ".join(reversed(result_parts))

