    char_counter = Counter(text)
    duplicates = {char: count for char, count in char_counter.items() if count > 1}
    return duplicates

if __name__ == '__main__':
    sample_text = "hello world, 你好世界! 🌍🌍"
    result = find_duplicate_characters(sample_text)
    print(result)

def filter_duplicate_chars(text):
    counts = {}
    for char in text:
        counts[char] = counts.get(char, 0) + 1
    result = []
    seen = set()
    for char in text:
        if counts[char] > 1 and char not in seen:
            result.append(char)
            seen.add(char)
    return ''.join(result)

if __name__ == '__main__':
    print(filter_duplicate_chars('programming'))

def find_repeated_characters(s: str) -> list:
    char_count = {}
    for char in s:
        char_count[char] = char_count.get(char, 0) + 1
    return [char for char, count in char_count.items() if count > 1]

if __name__ == '__main__':
    print(find_repeated_characters("hello world"))
    print(find_repeated_characters("abcdef"))
    print(find_repeated_characters("aabbcc"))
    print(find_repeated_characters(""))

def filter_repeated_characters(text):
    if not text:
        return ""
    counts = {}
    for char in text:
        if char in counts:
            counts[char] += 1
        else:
            counts[char] = 1
    result = []
    seen = set()
    for char in text:
        if counts[char] > 1 and char not in seen:
            result.append(char)
            seen.add(char)
    return "".join(result)

if __name__ == '__main__':
    sample_string = "programming"
    output = filter_repeated_characters(sample_string)
    print(output)

