    if not phone_number.startswith('+'):
        return False
    remainder = phone_number[1:]
    if not remainder.isdigit():
        return False
    length = len(remainder)
    total_length = length + 1
    if 8 <= total_length <= 14:
        return True
    if 8 <= length <= 11:
        first_part = remainder[:3]
