    if not phone_number.startswith('+'):
        return False

    rest = phone_number[1:]

    if not rest.isdigit():
        return False

    length = len(rest)

    if length < 8 or length > 13:
        return False

    first_part = rest[:3]
    second_part = rest[3:]

    if len(first_part) < 1 or len(first_part) > 3:
        return False

    if len(second_part) < 7 or len(second_part) > 10:
        return False

    if len(first_part) + len(second_part) != length:
        return False

    return True

