    def is_valid(phone_number):
        cleaned = re.sub(r'[^\d+]', '', phone_number)
        pattern = r'^\+?[1-9]\d{6,14}$'
        match = re.fullmatch(pattern, cleaned)
        original_clean = cleaned if cleaned else ""
