def to_camel_case(snake_str):
    if not snake_str:
        return ""
    parts = snake_str.split('_')
    if not parts:
        return ""
    first_part = parts[0]
    if not first_part:
        return ""
    result = [first_part]
    for part in parts[1:]:
        if not part:
            result.append("")
            continue
        result.append(part[0].upper() + part[1:])
    return "".join(result)

