    if not input_str:
        return ""

    result = []
    count = 1
    current_char = input_str[0]

    for i in range(1, len(input_str)):
        if input_str[i] == current_char:
            count += 1
        else:
            result.append(current_char + str(count))
            current_char = input_str[i]
            count = 1

    result.append(current_char + str(count))

    compressed = "".join(result)

    if len(compressed) >= len(input_str):
        return input_str

    return compressed

