def run_length_decode(input_string: str) -> str:
    if not input_string:
        return ""

    result = []
    count_str = []

    for char in input_string:
        if char.isdigit():
            count_str.append(char)
        else:
            count = int("".join(count_str))
            result.append(char * count)
            count_str = []

    return "".join(result)

