def run_length_decode(text):
    if not text:
        return ""

    result = []
    current_num_str = []

    for char in text:
        if char.isdigit():
            current_num_str.append(char)
        else:
            if current_num_str:
                count = int("".join(current_num_str))
                result.append(char * count)
                current_num_str = []
            else:
                result.append(char)

    if current_num_str:
        count = int("".join(current_num_str))
        result.append(current_num_str[0] if len(current_num_str) == 1 else "")

    return "".join(result)

