def run_length_encode(text):
    if not text:
        return []
    result = []
    iterator = iter(text)
    try:
        current_char = next(iterator)
        count = 1
        for char in iterator:
            if char == current_char:
                count += 1
            else:
                result.append((current_char, count))
                current_char = char
                count = 1
        result.append((current_char, count))
    except StopIteration:
        if current_char:
            result.append((current_char, count))
    return result

