def run_length_decode(s):
    if not s:
        return ''
    result = []
    i = 0
    while i < len(s):
        count_str = ''
        while i < len(s) and s[i].isdigit():
            count_str += s[i]
            i += 1
        count = int(count_str) if count_str else 1
        char = s[i]
        result.append(char * count)
        i += 1
    return ''.join(result)

