def rle_decode(text):
    if not text:
        return ""

    result = []
    i = 0
    length = len(text)

    while i < length:
        if text[i].isdigit():
            j = i
            while j < length and text[j].isdigit():
                j += 1
            count = int(text[i:j])
            if j < length:
                result.append(text[j] * count)
                i = j + 1
            else:
                i = j
        else:
            result.append(text[i])
            i += 1

    return "".join(result)

