def run_length_encode_fast(s: str) -> list:
    if not s:
        return []

    result = []
    prev = s[0]
    count = 1

    for char in s[1:]:
        if char == prev:
            count += 1
        else:
            result.append((prev, count))
            prev = char
            count = 1
    result.append((prev, count))
    return result

