import itertools

def compress_string(data):
    if not data:
        return ""

    def encode_segment(char, group_len):
        if group_len == 1:
            return char
        return str(group_len) + char

    grouped = itertools.groupby(data)
    encoded_parts = [
        encode_segment(char, len(list(items)))
        for char, items in grouped
    ]

    return "".join(encoded_parts)

if __name__ == '__main__':
    samples = ["", "a", "aaabbc", "abcde", "xxxx", "ab"]
    for sample in samples:
        print(compress_string(sample))

class RunLengthEncoder:
    def __init__(self, min_run_length):
        self.min_run_length = min_run_length

    def _format_run(self, character, count):
        if count >= self.min_run_length:
            return str(count) + character
        return character * count

    def encode(self, data):
        if not data:
            return ""
        result = []
        current_char = data[0]
        count = 1
        length = len(data)
        index = 1
        while index < length:
            char = data[index]
            if char == current_char:
                count += 1
            else:
                result.append(self._format_run(current_char, count))
                current_char = char
                count = 1
            index += 1
        result.append(self._format_run(current_char, count))
        return "".join(result)

