def run_length_decode(data: str) -> str:
    if not data:
        return ""

    result = []
    length = len(data)
    i = 0

    while i < length:
        count_str = []
        while i < length and data[i].isdigit():
            count_str.append(data[i])
            i += 1
        count = int("".join(count_str))
        char = data[i]
        i += 1
        result.append(char * count)

    return "".join(result)

