    if not encoded:
        return ""
    digits = []
    result_parts = []
    for char in encoded:
        if char.isdigit():
            digits.append(char)
        else:
            if digits:
                count = int("".join(digits))
                result_parts.append(char * count)
                digits = []
    return "".join(result_parts)

