    current_char = input_string[0]
    count = 1

    for char in input_string[1:]:
        if char == current_char:
            count += 1
        else:
            if count > 1:
                compressed.append(str(count))
            compressed.append(current_char)
            current_char = char
            count = 1

    if count > 1:
        compressed.append(str(count))
    compressed.append(current_char)

    return "".join(compressed)

