            if count > 1:
                result.append(f"{current_char}{count}")
            else:
                result.append(current_char)
            current_char = s[i]
            count = 1

    if count > 1:
        result.append(f"{current_char}{count}")
    else:
        result.append(current_char)

    return "".join(result)

