def rle_chunks(input_stream, chunk_size=1024):
    current_char = None
    count = 0
    buffer = []

    for char in input_stream:
        buffer.append(char)
        if len(buffer) > chunk_size:
            yield ''.join(buffer)
            buffer = []
            current_char = None
            count = 0
            continue

        if current_char is None:
            current_char = char
            count = 1
        elif char == current_char:
            count += 1
            if count > 255:
                buffer = buffer[:-count]
                buffer.append(f"{current_char}{count}")
                current_char = char
                count = 0
        else:
            if count > 0:
                if count > 1:
                    buffer.append(f"{current_char}{count}")
                else:
                    buffer.append(current_char)
            current_char = char
            count = 1

    if count > 0:
        if count > 1:
            buffer.append(f"{current_char}{count}")
        else:
            buffer.append(current_char)

    if buffer:
        yield ''.join(buffer)

