def decompress_rle(compressed_string):
    if not compressed_string:
        return ""
    decompressed = []
    count = ""
    for char in compressed_string:
        if char.isdigit():
            count += char
        else:
            if count:
                decompressed.append(char * int(count))
                count = ""
            else:
                decompressed.append(char)
    return ''.join(decompressed)

