import re
from itertools import groupby

def rle_encode(s):
    if not s:
        return ""
    result = []
    for char, group in groupby(s):
        count = sum(1 for _ in group)
        if count == 1:
            result.append(char)
        else:
            result.append(f"{count}{char}")
    return "".join(result)

