def enhanced_rle_decode(data: str) -> str:
    if not data:
        return ""
    result = []
    i = 0
    while i < len(data):
        char = data[i]
        if char.isdigit():
            raise ValueError("Invalid RLE format: unexpected digit at start")
        if i + 1 < len(data) and data[i + 1].isdigit():
            count_str = ""
            j = i + 1
            while j < len(data) and data[j].isdigit():
                count_str += data[j]
                j += 1
            count = int(count_str)
            result.append(char * count)
            i = j
        else:
            result.append(char)
            i += 1
    return "".join(result)

