def rle_compress(text):
    if not text:
        return ""
    result = []
    current_char = text[0]
    count = 1
    for char in text[1:]:
        if char == current_char:
            count += 1
        else:
            result.append(f"{count}{current_char}")
            current_char = char
            count = 1
    result.append(f"{count}{current_char}")
    return "".join(result)

def rle_decompress(text):
    if not text:
        return ""
    result = []
    i = 0
    length = len(text)
    while i < length:
        j = i
        while j < length and text[j].isdigit():
            j += 1
        if j == length:
            break
        count = int(text[i:j])
        char = text[j]
        result.append(char * count)
        i = j + 1
    return "".join(result)

if __name__ == '__main__':
    sample_text = "WWWWWWWWWWWWBWWWWWWWWWWWWWWBWWW"
    compressed = rle_compress(sample_text)
    decompressed = rle_decompress(compressed)
    print(f"Original: {sample_text}")
    print(f"Compressed: {compressed}")
    print(f"Decompressed: {decompressed}")

def rle_compress(data: str) -> str:
    if not data:
        return ""
    result = []
    length = len(data)
    i = 0
    while i < length:
        current_char = data[i]
        count = 1
        while i + 1 < length and data[i + 1] == current_char:
            count += 1
            i += 1
        result.append(f"{count}{current_char}")
        i += 1
    return "".join(result)

def rle_decompress(compressed: str) -> str:
    if not compressed:
        return ""
    result = []
    i = 0
    length = len(compressed)
    while i < length:
        count = 0
        while i < length and compressed[i].isdigit():
            count = count * 10 + int(compressed[i])
            i += 1
        if i < length:
            result.append(compressed[i] * count)
            i += 1
    return "".join(result)

