def rle_decompress(data):
    if not data:
        return ""
    result = []
    i = 0
    while i < len(data):
        num_start = i
        while i < len(data) and data[i].isdigit():
            i += 1
        if num_start == i:
            break
        count = int(data[num_start:i])
        if i < len(data):
            char = data[i]
            result.append(char * count)
            i += 1
    return "".join(result)

