class RLEEncoder:
    def __init__(self, data):
        self.data = data

    def encode(self):
        if not self.data:
            return []
        result = []
        current = self.data[0]
        count = 1
        for val in self.data[1:]:
            if val == current:
                count += 1
            else:
                result.append([current, count])
                current = val
                count = 1
        result.append([current, count])
        return result

    def decode(self):
        if not self.data:
            return []
        decoded = []
        for pair in self.data:
            value, times = pair
            decoded.extend([value] * times)
        return decoded

