def rle_decode(text: str) -> str:
    if not text:
        return ""

    result = []
    i = 0

    while i < len(text):
        count_str = []
        while i < len(text) and text[i].isdigit():
            count_str.append(text[i])
            i += 1

        count = int("".join(count_str))

        if i < len(text):
            char = text[i]
            i += 1
            result.append(char * count)

    return "".join(result)

