    sample_input = b"WWWWWWWWWWWWBWWWWWWWWWWWWBBBWWWWWWWWWWWWWWWWWWWWWWWWWWWWWWB"
    encoded = rle_encode(sample_input)
    decoded = rle_decode(encoded)
    print(encoded)
    print(decoded)
    print(encoded == rle_encode(decoded))

