import re

def decompress_rle(encoded: str) -> str:
    if not encoded:
        return ''
    pattern = re.compile(r'(\d*)(\D)')
    matches = pattern.findall(encoded)
    decoded_parts = [char * (int(count) if count else 1) for count, char in matches]
    return ''.join(decoded_parts)

