def rle_decode(compressed: str) -> str:
    if not compressed:
        return ""

    decoded_parts = []
    i = 0
    n = len(compressed)

    while i < n:
        count_str = ""
        while i < n and compressed[i].isdigit():
            count_str += compressed[i]
            i += 1

        if not count_str:
            count = 1
        else:
            count = int(count_str)

        if i < n:
            char = compressed[i]
            i += 1
            decoded_parts.append(char * count)
        else:
            break

    return "".join(decoded_parts)

