def decode_rle(compressed: str) -> str:
    if not compressed:
        return ""

    result = []
    i = 0
    n = len(compressed)

    while i < n:
        char = compressed[i]
        i += 1

        if i >= n:
            result.append(char)
            break

        count_str = []
        while i < n and compressed[i].isdigit():
            count_str.append(compressed[i])
            i += 1

        if count_str:
            count = int("".join(count_str))
            result.append(char * count)
        else:
            result.append(char)

    return "".join(result)

