def rle_decode(compressed: str) -> str:
    result = []
    num_buffer = []
    for char in compressed:
        if char.isdigit():
            num_buffer.append(char)
        else:
            if num_buffer:
                count = int(''.join(num_buffer))
                num_buffer = []
                result.append(char * count)
            else:
                result.append(char)
