class RLE:
    def encode(self, s):
        if not s:
            return ""
        result = []
        count = 1
        for i in range(1, len(s)):
            if s[i] == s[i-1]:
                count += 1
            else:
                result.append(str(count) + s[i-1])
                count = 1
        result.append(str(count) + s[-1])
        return "".join(result)

    def decode(self, s):
        if not s:
            return ""
        result = []
        i = 0
        while i < len(s):
            num_str = ""
            while i < len(s) and s[i].isdigit():
                num_str += s[i]
                i += 1
            count = int(num_str)
            if i < len(s):
                result.append(s[i] * count)
                i += 1
        return "".join(result)

