def run_length_decode(encoded: str) -> str:
    decoded = []
    num_str = []

    for char in encoded:
        if char.isdigit():
            num_str.append(char)
        else:
            if num_str:
                count = int(''.join(num_str))
                decoded.append(char * count)
                num_str = []
            else:
                decoded.append(char)

    if num_str:
        count = int(''.join(num_str))
        if decoded:
            last_char = decoded.pop()
            decoded.append(last_char * count)
        else:
            decoded.append(last_char * count)

    return ''.join(decoded)

