class RLEManager:
    def __init__(self):
        self.default_separator = ""

    def compress(self, data):
        if not isinstance(data, str):
            return str(data)
        if not data:
            return ""
        result_parts = []
        current_char = data[0]
        run_length = 1
        for index in range(1, len(data)):
            char = data[index]
            if char == current_char:
                run_length += 1
            else:
                result_parts.append(self._format_pair(current_char, run_length))
                current_char = char
                run_length = 1
        result_parts.append(self._format_pair(current_char, run_length))
        return "".join(result_parts)

    def decompress(self, data):
        if not isinstance(data, str):
            return str(data)
        if not data:
            return ""
        result_chars = []
        index = 0
        length = len(data)
        while index < length:
            if data[index].isdigit():
                start = index
                while index < length and data[index].isdigit():
                    index += 1
                count_str = data[start:index]
                count = int(count_str)
                if index < length:
                    char = data[index]
                    result_chars.append(char * count)
                    index += 1
                else:
                    return ""
            else:
                result_chars.append(data[index])
                index += 1
        return "".join(result_chars)

    def _format_pair(self, character, count):
        if count > 1:
            return str(count) + character
        return character

