        current_char = s[0]
        for i in range(1, len(s)):
            if s[i] == current_char:
                count += 1
            else:
                compressed.append(f"{count}{current_char}")
                current_char = s[i]
                count = 1
        compressed.append(f"{count}{current_char}")
