    def decompress(self, s):
        if not s:
            return ""
        decompressed = []
        i = 0
        while i < len(s):
            num_str = ""
            while i < len(s) and s[i].isdigit():
                num_str += s[i]
                i += 1
            if not num_str:
                break
            if i < len(s):
                char = s[i]
                count = int(num_str)
                decompressed.append(char * count)
                i += 1
            else:
                break
        return "".join(decompressed)

