def rle_decode(data: str) -> str:
    if not data:
        return ""

    result = []
    i = 0
    length = len(data)

    while i < length:
        count_str = []
        while i < length and data[i].isdigit():
            count_str.append(data[i])
            i += 1
        count = int("".join(count_str))
        char = data[i]
        result.append(char * count)
        i += 1

    return "".join(result)

