def run_length_decode(text: str) -> str:
    if not text:
        return ""

    result = []
    i = 0
    length = len(text)

    while i < length:
        count_str = []
        while i < length and text[i].isdigit():
            count_str.append(text[i])
            i += 1

        if not count_str:
            count = 1
        else:
            count = int("".join(count_str))

        if i < length:
            char = text[i]
            result.append(char * count)
            i += 1

    return "".join(result)

