def rle_decode(data):
    if not data or len(data) % 2 != 0:
        raise ValueError("Invalid encoded data")

    result = bytearray()
    for i in range(0, len(data), 2):
        value = data[i]
        count = data[i + 1]
        result.extend([value] * count)

    return result

