def run_length_decode(encoded):
    decoded = []
    i = 0
    while i < len(encoded):
        count = ""
        while i < len(encoded) and encoded[i].isdigit():
            count += encoded[i]
            i += 1
        if not count:
            count = 1
        else:
            count = int(count)

        if i < len(encoded):
            char = encoded[i]
            decoded.append(char * count)
            i += 1

    return "".join(decoded)

