def _encode_rle(text):
    if not text:
        return ""
    result = []
    current_char = text[0]
    current_count = 1
    index = 1
    text_length = len(text)
    while index < text_length:
        char = text[index]
        if char == current_char:
            current_count += 1
        else:
            result.append(f"{current_count}{current_char}")
            current_char = char
            current_count = 1
        index += 1
    result.append(f"{current_count}{current_char}")
    return "".join(result)

