    while i < n:
        char = compressed[i]
        i += 1
        if i >= n or not compressed[i].isdigit():
            result.append(char)
        else:
            num_str = []
            while i < n and compressed[i].isdigit():
                num_str.append(compressed[i])
                i += 1
            count = int(''.join(num_str))
            if count < 0:
                raise ValueError("Count cannot be negative")
            result.append(char * count)
