    result = []
    i = 0
    n = len(compressed)

    while i < n:
        if i + 1 < n and compressed[i].isdigit():
            count_str = ""
            while i < n and compressed[i].isdigit():
                count_str += compressed[i]
                i += 1

            if count_str:
