def decompress_rle(compressed: str) -> str:
    if not compressed:
        return ""

    result = []
    current_digit = []

    for char in compressed:
        if char.isdigit():
            current_digit.append(char)
        else:
            if current_digit:
                count = int("".join(current_digit))
                result.append(char * count)
                current_digit = []
            else:
                result.append(char)

    if current_digit:
        count = int("".join(current_digit))
        result.append("*" * count)

    return "".join(result)

