    for char in data[1:]:
        if char == current_char:
            count += 1
        else:
            if count > 1:
                encoded.append(str(count))
            encoded.append(current_char)
            current_char = char
            count = 1
    if count > 1:
        encoded.append(str(count))
    encoded.append(current_char)
    return ''.join(encoded)

def rle_decode(data):
    if not data:
        return ''
    decoded = []
    i = 0
    while i < len(data):
        if data[i].isdigit():
            count = 0
            while i < len(data) and data[i].isdigit():
                count = count * 10 + int(data[i])
                i += 1
            if i < len(data):
                decoded.append(data[i] * count)
                i += 1
        else:
            decoded.append(data[i])
            i += 1
    return ''.join(decoded)

