def decompress_rle(data: str) -> str:
    if not data:
        return ""
    result = []
    i = 0
    while i < len(data):
        if not data[i].isdigit():
            return ""
        j = i
        while j < len(data) and data[j].isdigit():
            j += 1
        count = int(data[i:j])
        if j >= len(data):
            return ""
        char = data[j]
        result.append(char * count)
        i = j + 1
    return "".join(result)

