def rle_decompress(data):
    if not data:
        return ""
    result = []
    i = 0
    length = len(data)
    while i < length:
        count_str = ""
        while i < length and data[i].isdigit():
            count_str += data[i]
            i += 1
        if i >= length:
            break
        char = data[i]
        i += 1
        count = int(count_str) if count_str else 1
        result.append(char * count)
    return "".join(result)

