def run_length_encode(data: str) -> str:
    if not data:
        return ''
    encoded = []
    current_char = data[0]
    count = 1
    for char in data[1:]:
        if char == current_char:
            count += 1
        else:
            if count > 3:
                encoded.append(f'{count}{current_char}')
            elif count > 1:
                encoded.append(f'{count}{current_char}')
            else:
                encoded.append(current_char)
            current_char = char
            count = 1
    if count > 3:
        encoded.append(f'{count}{current_char}')
    elif count > 1:
        encoded.append(f'{count}{current_char}')
    else:
        encoded.append(current_char)
    return ''.join(encoded)

def run_length_decode(data: str) -> str:
    if not data:
        return ''
    decoded = []
    length = len(data)
    i = 0
    while i < length:
        char = data[i]
        if char.isdigit():
            j = i
            while j < length and data[j].isdigit():
                j += 1
            count = int(data[i:j])
            if j < length:
                next_char = data[j]
                decoded.append(next_char * count)
                i = j + 1
            else:
                decoded.append(char)
                i += 1
        else:
            decoded.append(char)
            i += 1
    return ''.join(decoded)
