        while i < len(data):
            if i + 1 < len(data) and data[i+1].isdigit():
                char = data[i]
                count = int(data[i+1])
                decoded.append(char * count)
                i += 2
            else:
                decoded.append(data[i])
                i += 1
        return "".join(decoded)

