def decode_rle(data: str) -> str:
    if not data:
        return ""
    result = []
    count_str = ""
    for char in data:
        if char.isdigit():
            count_str += char
        else:
            if count_str:
                count = int(count_str)
                result.append(char * count)
                count_str = ""
            else:
                result.append(char)
    return "".join(result)

