    rle = RLE()
    original = "aaaabbbcc"
    encoded = rle.encode(original)
    print(encoded)
    decoded = rle.decode(encoded)
    print(decoded)

def compress_string(s):
    if not s:
        return ''

    result = []
    i = 0
    n = len(s)

    while i < n:
        char = s[i]
        count = 1
        while i + count < n and s[i + count] == char:
            count += 1

        if count == 1:
            result.append(char)
        else:
            result.append(str(count))
            result.append(char)

        i += count

    return ''.join(result)

