        for i in range(1, len(data)):
            if data[i] == data[i - 1]:
                count += 1
            else:
                encoded.append(f"{count}{data[i - 1]}")
                count = 1
        encoded.append(f"{count}{data[-1]}")
        return "".join(encoded)

