    if not s:
        return ""
    if len(s) == 1:
        return s[0] + "1"

    encoded = []
    current_char = s[0]
    count = 1

    for i in range(1, len(s)):
        if s[i] == current_char:
            count += 1
        else:
            encoded.append(current_char + str(count))
