def run_length_decode(s):
    if not s:
        return ""

    decoded = []
    i = 0
    while i < len(s):
        char = s[i]
        j = i + 1
        while j < len(s) and s[j].isdigit():
            j += 1
        count = int(s[i+1:j]) if i+1 < j else 1
        decoded.append(char * count)
        i = j

    return ''.join(decoded)

