def run_length_encode(s):
    if not s:
        return ""

    if len(s) == 1:
        return s + "1"

    result = []
    current_char = s[0]
    count = 1

    for i in range(1, len(s)):
        if s[i] == current_char:
            count += 1
        else:
            result.append(current_char)
            result.append(str(count))
            current_char = s[i]
            count = 1

    result.append(current_char)
    result.append(str(count))

    return "".join(result)

