def run_length_decode(data: str) -> str:
    if not data:
        return ""
    decoded = []
    i = 0
    length = len(data)
    while i < length:
        num_str = []
        while i < length and data[i].isdigit():
            num_str.append(data[i])
            i += 1
        count = int("".join(num_str))
        if i < length:
            char = data[i]
            i += 1
            decoded.append(char * count)
    return "".join(decoded)

