    if not encoded_string:
        return ""

    result = []
    count = 0
    i = 0
    n = len(encoded_string)

    while i < n:
        char = encoded_string[i]
        if char.isdigit():
            while i < n and encoded_string[i].isdigit():
                count = count * 10 + int(encoded_string[i])
                i += 1
        else:
            if count == 0:
                count = 1
            result.append(char * count)
            count = 0
            i += 1

    return "".join(result)

