def run_length_encode(data: str) -> str:
    if not data:
        return ""
    result = []
    n = len(data)
    i = 0
    while i < n:
        current_char = data[i]
        count = 1
        while i + 1 < n and data[i + 1] == current_char:
            i += 1
            count += 1
        if count > 9:
            result.append(str(count % 10))
            result.append(current_char)
            remaining = count // 10
            while remaining > 0:
                result.append(str(remaining % 10))
                result.append(current_char)
                remaining //= 10
        else:
            result.append(str(count))
            result.append(current_char)
        i += 1
    return "".join(result)

