            result.append(encoded_data[i])
            i += 1
            continue
        count = 0
        while i < n and encoded_data[i].isdigit():
            count = count * 10 + int(encoded_data[i])
            i += 1
        if i < n:
            result.append(encoded_data[i] * count)
            i += 1
        else:
