    return ''.join(decoded)

def bidirectional_rle(data: str, mode: str = 'encode') -> any:
    if mode == 'encode':
        return run_length_encode(data)
    elif mode == 'decode':
        return run_length_decode(data)
    else:
        raise ValueError("Mode must be 'encode' or 'decode'")

