        return ""

    encoded_chars = []
    count = 1
    prev_char = sequence[0]

    for current_char in sequence[1:]:
        if current_char == prev_char:
            count += 1
        else:
            encoded_chars.append(f"{count}{prev_char}")
            prev_char = current_char
            count = 1
    encoded_chars.append(f"{count}{prev_char}")
