def _rle_generator(s):
    if not s:
        return
    current_char = s[0]
    count = 1
    for char in s[1:]:
        if char == current_char:
            count += 1
        else:
            yield current_char, range(count)
            current_char = char
            count = 1
    yield current_char, range(count)

