def run_length_decode(s):
    if not s:
        return ""

    decoded = []
    i = 0

    while i < len(s):
        count_str = ""
        while i < len(s) and s[i].isdigit():
            count_str += s[i]
            i += 1

        if count_str:
            count = int(count_str)
            if i < len(s):
                char = s[i]
                decoded.append(char * count)
                i += 1

    return "".join(decoded)

