def run_length_decode(s):
    decoded = []
    i = 0
    while i < len(s):
        count = ""
        while i < len(s) and s[i].isdigit():
            count += s[i]
            i += 1
        if i < len(s):
            char = s[i]
            i += 1
            decoded.append(char * int(count))
    return "".join(decoded)

