    if not input_string:
        return ""

    encoded_chars = []
    count = 1
    length = len(input_string)

    for i in range(1, length):
        if input_string[i] == input_string[i - 1]:
            count += 1
        else:
            encoded_chars.append(f"{count}{input_string[i - 1]}")
            count = 1

    encoded_chars.append(f"{count}{input_string[-1]}")

    return "".join(encoded_chars)

