def rle_encode(s: str) -> list:
    if not s:
        return []
    result = [(s[0], 1)]
    for c in s[1:]:
        if c == result[-1][0]:
            result[-1] = (result[-1][0], result[-1][1] + 1)
        else:
            result.append((c, 1))
    return result

