def rle_decode(text):
    decoded = []
    i = 0
    while i < len(text):
        if text[i].isdigit():
            count = 0
            while i < len(text) and text[i].isdigit():
                count = count * 10 + int(text[i])
                i += 1
            char = text[i]
            decoded.append(char * count)
            i += 1
        else:
            decoded.append(text[i])
            i += 1

    return ''.join(decoded)

