import itertools
import operator

def rle_encode(text: str) -> str:
    if not text:
        return ""

    def _format_group(key, group):
        count = len(list(group))
        if count == 1:
            return f"{key}"
        return f"{count}{key}"

    encoded_parts = [
        _format_group(key, group)
        for key, group in itertools.groupby(text)
    ]

    return "".join(encoded_parts)

