    encoded = ['{}{}'.format(len(group), char) for char, group in _group_by_char(s)]
    return ''.join(encoded)

def _group_by_char(s):
    if not s:
        return []
    result = []
    current_char = s[0]
    count = 1
    for char in s[1:]:
        if char == current_char:
            count += 1
        else:
            result.append((current_char, [char] * count))
            current_char = char
            count = 1
    result.append((current_char, [char] * count))
    return result

