def decompress_string(encoded_string):
    result = []
    chars = list(encoded_string)
    i = 0
    while i < len(chars):
        char = chars[i]
        i += 1
        num_str = ""
        while i < len(chars) and chars[i].isdigit():
            num_str += chars[i]
            i += 1
        count = int(num_str) if num_str else 1
        result.append(char * count)
    return "".join(result)

