def rle_generator(data):
    if not data:
        return
    count = 1
    length = len(data)
    for i in range(1, length):
        if data[i] == data[i - 1]:
            count += 1
        else:
            yield data[i - 1], count
            count = 1
    yield data[length - 1], count

