    count = 1
    length = len(text)

    for i in range(1, length):
        if text[i] == current_char:
            count += 1
        else:
            if count > 2:
                result.append(current_char)
                result.append(str(count))
            else:
                result.extend([current_char] * count)
            current_char = text[i]
            count = 1

