def decompress_text(text):
    if not text:
        return ""

    result = []
    i = 0

    while i < len(text):
        count_str = []
        while i < len(text) and text[i].isdigit():
            count_str.append(text[i])
            i += 1

        if not count_str:
            i += 1
            continue

        count = int("".join(count_str))

        if i < len(text):
            char = text[i]
            i += 1
            result.append(char * count)
        else:
            result.append(str(int("".join(count_str))))

    return "".join(result)

