def run_length_decode(text: str) -> str:
    if not text:
        return ""

    result = []
    i = 0
    while i < len(text):
        count_str = ""
        while i < len(text) and text[i].isdigit():
            count_str += text[i]
            i += 1
        if i < len(text):
            char = text[i]
            i += 1
            result.append(char * int(count_str))
    return "".join(result)

