import sys

def int_to_twos_complement(n, bits=8):
    if n < 0:
        mask = (1 << bits) - 1
        return format(n & mask, f'0{bits}b')
    return format(n, f'0{bits}b')

def twos_complement_to_int(binary_str, bits=None):
    if bits is None:
        bits = len(binary_str)
    if binary_str[0] == '1':
        value = int(binary_str, 2) - (1 << bits)
        return value
    return int(binary_str, 2)

if __name__ == '__main__':
    test_values = [-5, -128, 0, 7, -1]
    for val in test_values:
        binary_rep = int_to_twos_complement(val, 8)
        recovered_val = twos_complement_to_int(binary_rep, 8)
        print(f'{val}: {binary_rep} -> {recovered_val}')

def twos_complement_binary(number):
    if number >= 0:
        return bin(number)[2:]
    bit_length = len(bin(number & 0xFFFFFFFF)[2:])
    mask = (1 << bit_length) - 1
    complement = number & mask
    return bin(complement)[2:]

if __name__ == '__main__':
    sample_values = [-1, -5, -10, 0, 5, 10, -2**8, 2**8]
    for value in sample_values:
        result = twos_complement_binary(value)
        print(f"twos_complement_binary({value}) -> '{result}'")

def to_twos_complement(n, bits=8):
    mask = (1 << bits) - 1
    if n < 0:
        val = (1 << bits) + n
    else:
        val = n
    if val < 0 or val > mask:
        raise ValueError(f"Value {n} out of range for {bits} bits")
    binary = bin(val & mask)[2:].zfill(bits)
    return binary

