def to_twos_complement(n, bits=8):
    if n >= 0:
        binary = bin(n)[2:]
        if len(binary) > bits:
            raise ValueError(f"Value {n} does not fit in {bits} bits")
        return binary.zfill(bits)
    else:
        if n < -(2**(bits - 1)):
            raise ValueError(f"Value {n} is out of range for {bits} bits")
        mask = 2**bits
        result = bin(mask + n)[2:]
        if len(result) > bits:
            raise ValueError(f"Value {n} does not fit in {bits} bits")
        return result.zfill(bits)

