def compress_string(s):
    if not s:
        return ''
    compressed = []
    count = 1
    current_char = s[0]
    for i in range(1, len(s)):
        if s[i] == current_char:
            count += 1
        else:
            compressed.append(current_char)
            compressed.append(str(count))
            current_char = s[i]
            count = 1
    compressed.append(current_char)
    compressed.append(str(count))
    return ''.join(compressed)

