def compress_string(input_string):
    if not input_string:
        return ""
    result = []
    count = 1
    length = len(input_string)
    for i in range(length):
        if i + 1 < length and input_string[i] == input_string[i + 1]:
            count += 1
        else:
            result.append(f"{input_string[i]}{count}")
            count = 1
    return "".join(result)

