    if n >= 0:
        if bits is None:
            return bin(n)[2:]
        else:
            return bin(n)[2:].zfill(bits)
    else:
        if bits is None:
            bits = n.bit_length() + 1
        mask = (1 << bits) - 1
        twos_complement = n & mask
        return bin(twos_complement)[2:].zfill(bits)

