def to_twos_complement(n, bits=8):
    if n == 0:
        return "0" * bits
    if n < 0:
        masked_val = (1 << bits) + n
        return bin(masked_val)[2:].zfill(bits)
    if n >= (1 << bits):
        raise ValueError(f"Value {n} exceeds {bits}-bit representation range")
    return bin(n)[2:].zfill(bits)

