        print(f"{value} (16-bit): {result_16}")

def to_twos_complement(value, bits=None):
    if bits is None:
        if value >= 0:
            return bin(value)[2:]
        bit_length = value.bit_length()
        bits = bit_length + 2
    if value < 0:
        value = (1 << bits) + value
    return bin(value)[2:].zfill(bits)

