def decimal_to_fixed_binary(number: int, bit_length: int) -> str:
    binary_repr = bin(number)[2:]
    if len(binary_repr) > bit_length:
        binary_repr = binary_repr[-bit_length:]
    else:
        binary_repr = '0' * (bit_length - len(binary_repr)) + binary_repr
    return binary_repr

