    if decimal_number < 0:
        return '-' + decimal_to_binary(-decimal_number)
    if decimal_number == 0:
        return '0'
    stack = []
    while decimal_number > 0:
        stack.append(decimal_number % 2)
        decimal_number = decimal_number // 2
