def decimal_to_binary_bit_length(value: int, bit_length: int) -> str:
    binary = bin(value)[2:]
    padding = bit_length - len(binary)
    if padding < 0:
        raise ValueError(f"Bit length {bit_length} is too small for value {value}")
    return '0' * padding + binary

