def binary_to_decimal(binary_str):
    if not binary_str:
        return 0
    result = 0
    power = 1
    for index in range(len(binary_str) - 1, -1, -1):
        digit = binary_str[index]
        if digit == '1':
            result += power
        power *= 2
    return result

