class BinaryConverter:
    ZERO = "0"
    ONE = "1"

    @staticmethod
    def to_binary(n):
        if n == 0:
            return BinaryConverter.ZERO
        result = []
        while n > 0:
            if n & 1:
                result.append(BinaryConverter.ONE)
            else:
                result.append(BinaryConverter.ZERO)
            n >>= 1
        return "".join(reversed(result))

