        if '0' <= char <= '9':
            digit = ord(char) - ord('0')
        elif 'a' <= char <= 'f':
            digit = ord(char) - ord('a') + 10
        else:
            digit = ord(char) - ord('A') + 10
        result = result * 16 + digit
    if is_negative:
        return -result
    return result

