from functools import reduce

def hex_to_decimal(hex_string):
    def accumulator(current_value, char):
        if char.isdigit():
            digit = int(char)
        else:
            digit = ord(char.lower()) - ord('a') + 10
        return current_value * 16 + digit

    return reduce(accumulator, hex_string, 0)

