def hex_to_int(hex_str):
    result = 0
    for char in hex_str.lower():
        if '0' <= char <= '9':
            value = ord(char) - ord('0')
        elif 'a' <= char <= 'f':
            value = ord(char) - ord('a') + 10
        else:
            raise ValueError("Invalid hex character")
        result = result * 16 + value
    return result

