    result = 0
    for char in hex_string:
        result *= 16
        if '0' <= char <= '9':
            result += ord(char) - ord('0')
        elif 'a' <= char <= 'f':
            result += ord(char) - ord('a') + 10
        elif 'A' <= char <= 'F':
            result += ord(char) - ord('A') + 10
    return result

