def hex_to_decimal(hex_str):
    if not isinstance(hex_str, str):
        return 0
    stripped = hex_str.strip()
    if not stripped:
        return 0
    lower = stripped.lower()
    if lower.startswith('0x'):
        numeric_part = lower[2:]
    else:
        numeric_part = lower
    if not numeric_part:
        return 0
    for char in numeric_part:
        if char not in '0123456789abcdef':
            return 0
