        value_map[str(i)] = i
    for i in range(6):
        value_map[chr(ord('a') + i)] = 10 + i
        value_map[chr(ord('A') + i)] = 10 + i

    result = 0
    power = 1

    for char in reversed(hex_string):
        if char not in value_map:
            raise ValueError(f"Invalid hexadecimal character: {char}")
        digit_value = value_map[char]
        result += digit_value * power
        power *= 16

    return result

