            digit_value: int = ord(char) - ord("0")
        elif "a" <= char <= "f":
            digit_value = ord(char) - ord("a") + 10
        else:
            raise ValueError(f"Invalid hexadecimal character: {char}")
        decimal_value += digit_value * power
        power *= 16
    return decimal_value

