}

def binary_to_hex_map(binary_str: str) -> str:
    if not binary_str:
        return ''
    if len(binary_str) % 4 != 0:
        binary_str = '0' * (4 - (len(binary_str) % 4)) + binary_str
    hex_result = []
    for i in range(0, len(binary_str), 4):
        nibble = binary_str[i:i+4]
        val = int(nibble, 2)
        hex_result.append(BINARY_TO_HEX[str(val)])
