        if n == 0:
            return '0'
        hex_chars = '0123456789ABCDEF'
        result = []
        is_negative = n < 0
        if is_negative:
            n = -n
        while n > 0:
            remainder = n & 0xF
            result.append(hex_chars[remainder])
            n = n >> 4
        if is_negative:
