        raise ValueError("Input must contain only binary digits 0 and 1")

    if len(cleaned) % 4 != 0:
        padding_length = 4 - (len(cleaned) % 4)
        cleaned = '0' * padding_length + cleaned

    decimal_value = int(cleaned, 2)
    return format(decimal_value, 'X')

