def to_upper_hex(n):
    if n < 0:
        raise ValueError("Only non-negative integers are supported")
    if n == 0:
        return "0"
    hex_chars = "0123456789ABCDEF"
    result = ""
    while n > 0:
        remainder = n & 15
        digit = hex_chars[remainder]
        result = digit + result
        n >>= 4
    return result

