    binary_string = binary_string.lstrip('0')

    if not binary_string:
        return '0'

    value = 0
    for char in binary_string:
        value = (value << 1) | (1 if char == '1' else 0)

    hex_digits = '0123456789ABCDEF'
    hex_result = ''

    if value == 0:
        return '0'

    while value > 0:
        remainder = value & 15
