    remainder = len(binary_string) % 4
    if remainder != 0:
        binary_string = '0' * (4 - remainder) + binary_string

    hex_digits = '0123456789ABCDEF'
    result = []

    for i in range(0, len(binary_string), 4):
        chunk = binary_string[i:i+4]
        value = 0
        for bit in chunk:
            value = (value << 1) | (1 if bit == '1' else 0)
