import collections

def shortest_path(grid):
    if not grid or not grid[0]:
        return []

    rows = len(grid)
    cols = len(grid[0])
    start = None
    end = None

    for r in range(rows):
        for c in range(cols):
            if grid[r][c] == 0:
                if start is None:
                    start = (r, c)
                end = (r, c)

    if start is None or end is None:
        return []

    if start == end:
        return [start]

    queue = collections.deque([(start, [start])])
    visited = {start}

    directions = [(0, 1), (0, -1), (1, 0), (-1, 0)]

    while queue:
        (r, c), path = queue.popleft()

        for dr, dc in directions:
            nr, nc = r + dr, c + dc

            if 0 <= nr < rows and 0 <= nc < cols:
                if (nr, nc) not in visited and grid[nr][nc] == 0:
                    new_path = path + [(nr, nc)]

                    if (nr, nc) == end:
                        return new_path

                    visited.add((nr, nc))
                    queue.append(((nr, nc), new_path))

    return []

