import heapq
from typing import List, Tuple, Optional

def shortest_path_binary_grid(grid: List[List[int]]) -> Optional[List[Tuple[int, int]]]:
    if not grid or not grid[0]:
        return None
    rows = len(grid)
    cols = len(grid[0])
    if grid[0][0] == 1 or grid[rows - 1][cols - 1] == 1:
        return None
    start = (0, 0)
    target = (rows - 1, cols - 1)
    pq = [(0, 0, 0)]
    visited = set()
    visited.add((0, 0))
    parent = {start: None}
    directions = [(0, 1), (0, -1), (1, 0), (-1, 0)]
    while pq:
        cost, x, y = heapq.heappop(pq)
        if (x, y) == target:
            path = []
            current = target
            while current is not None:
                path.append(current)
                current = parent.get(current)
            return list(reversed(path))
        for dx, dy in directions:
            nx, ny = (x + dx, y + dy)
            if 0 <= nx < rows and 0 <= ny < cols:
                if (nx, ny) not in visited and grid[nx][ny] == 0:
                    visited.add((nx, ny))
                    parent[nx, ny] = (x, y)
                    heapq.heappush(pq, (cost + 1, nx, ny))
    return None
if __name__ == '__main__':
    sample_grid = [[0, 0, 0, 0], [1, 1, 0, 1], [0, 0, 0, 0], [0, 1, 1, 0]]
    result = shortest_path_binary_grid(sample_grid)
    print(result)

import heapq

class GridPathfinder:
    def __init__(self, grid):
        self.grid = grid
        self.rows = len(grid)
        self.cols = len(grid[0]) if self.rows > 0 else 0
        self.start = None
        self.end = None
        self.obstacles = set()
        self._parse_grid()

    def _parse_grid(self):
        for r in range(self.rows):
            for c in range(self.cols):
                cell = self.grid[r][c]
                if cell == 'S':
                    self.start = (r, c)
                elif cell == 'E':
                    self.end = (r, c)
                elif cell == 'X':
                    self.obstacles.add((r, c))

    def _heuristic(self, node):
        dr = abs(node[0] - self.end[0])
        dc = abs(node[1] - self.end[1])
        return dr + dc

    def _get_neighbors(self, node):
        r, c = node
        directions = [(-1, 0), (1, 0), (0, -1), (0, 1)]
        neighbors = []
        for dr, dc in directions:
            nr, nc = r + dr, c + dc
            if 0 <= nr < self.rows and 0 <= nc < self.cols and (nr, nc) not in self.obstacles:
                neighbors.append((nr, nc))
        return neighbors

    def find_path(self):
        if not self.start or not self.end:
            return []

        open_set = []
        heapq.heappush(open_set, (0, 0, self.start))
        came_from = {}
        g_score = {self.start: 0}
        f_score = {self.start: self._heuristic(self.start)}
        closed_set = set()

        while open_set:
            _, current_idx, current = heapq.heappop(open_set)

            if current == self.end:
                path = []
                while current in came_from:
                    path.append(current)
                    current = came_from[current]
                path.append(self.start)
                path.reverse()
                return path

            if current in closed_set:
                continue
            closed_set.add(current)

            for neighbor in self._get_neighbors(current):
                if neighbor in closed_set:
                    continue

                tentative_g = g_score.get(current, float('inf')) + 1

                if tentative_g < g_score.get(neighbor, float('inf')):
                    came_from[neighbor] = current
                    g_score[neighbor] = tentative_g
                    f = tentative_g + self._heuristic(neighbor)
                    f_score[neighbor] = f
                    entry = (f, current_idx + 1, neighbor)
                    heapq.heappush(open_set, entry)

        return []

