    rows = len(grid)
    cols = len(grid[0])
    if grid[0][0] == 1 or grid[rows - 1][cols - 1] == 1:
        return None
    queue = deque([(0, 0, [(0, 0)])])
    visited = [[False] * cols for _ in range(rows)]
    visited[0][0] = True
    directions = [(-1, 0), (1, 0), (0, -1), (0, 1)]
    while queue:
        r, c, path = queue.popleft()
        if r == rows - 1 and c == cols - 1:
