import collections

def shortest_path(grid):
    if not grid or not grid[0]:
        return None

    rows = len(grid)
    cols = len(grid[0])

    if grid[0][0] == 1 or grid[rows - 1][cols - 1] == 1:
        return None

    queue = collections.deque([(0, 0, 1)])
    visited = [[False] * cols for _ in range(rows)]
    visited[0][0] = True

    directions = [(0, 1), (1, 0), (0, -1), (-1, 0)]

    while queue:
        r, c, dist = queue.popleft()

