        return float('inf')

    if start == end:
        return grid[start[0]][start[1]]

    dist = [[float('inf')] * cols for _ in range(rows)]
    dist[0][0] = grid[0][0]
    heap = [(grid[0][0], 0, 0)]
    visited = set([(0, 0)])
    directions = [(0, 1), (0, -1), (1, 0), (-1, 0)]

    while heap:
        d, r, c = heapq.heappop(heap)

        if (r, c) == end:
