            elif grid[r][c] == 'E':
                end = (r, c)

    if start is None or end is None:
        return None

    sr, sc = start
    er, ec = end

    if sr < 0 or sr >= rows or sc < 0 or sc >= cols:
        return None
    if er < 0 or er >= rows or ec < 0 or ec >= cols:
        return None

    if grid[sr][sc] != 'S' or grid[er][ec] != 'E':
        return None

    directions = [(-1, 0), (1, 0), (0, -1), (0, 1)]
    queue = collections.deque([(sr, sc, [])])
    visited = set()
