def shortest_path(grid):
    if not grid or not grid[0]:
        return -1

    rows = len(grid)
    cols = len(grid[0])

    start = None
    end = None

    for r in range(rows):
        for c in range(cols):
            if grid[r][c] == 1:
                start = (r, c)
            elif grid[r][c] == 2:
                end = (r, c)

    if start is None or end is None:
        return -1

    if start == end:
        return 0

    visited = set()
    visited.add(start)
    queue = deque([(start, 0)])
    directions = [(0, 1), (0, -1), (1, 0), (-1, 0)]

    while queue:
        (r, c), dist = queue.popleft()

        for dr, dc in directions:
            nr, nc = r + dr, c + dc

            if 0 <= nr < rows and 0 <= nc < cols:
                if (nr, nc) == end:
                    return dist + 1

                if grid[nr][nc] != 0 and (nr, nc) != end:
                    continue

                if (nr, nc) not in visited:
                    visited.add((nr, nc))
                    queue.append(((nr, nc), dist + 1))

    return -1

