                start_node = (r, c)
            elif grid[r][c] == 2:
                end_node = (r, c)

    if not start_node or not end_node:
        return -1

    queue = deque()
    queue.append((start_node, 0))
    visited = set()
    visited.add(start_node)

    directions = [(0, 1), (0, -1), (1, 0), (-1, 0)]

    while queue:
        (curr_r, curr_c), dist = queue.popleft()

        if (curr_r, curr_c) == end_node:
