        for dr, dc in directions:
            nr, nc = r + dr, c + dc
            if 0 <= nr < rows and 0 <= nc < cols and (nr, nc) not in visited and grid[nr][nc] != 'X':
                visited.add((nr, nc))
                queue.append((nr, nc, steps + 1))
    return -1

