    cols = len(grid[0]) if rows > 0 else 0
    if grid[start[0]][start[1]] == 1 or grid[goal[0]][goal[1]] == 1:
        return None
    if start == goal:
        return [start]
    open_set = []
    heapq.heappush(open_set, (0, start))
    came_from = {}
    g_score = {}
    g_score[start] = 0
    f_score = {}
    f_score[start] = heuristic(start, goal)
    while open_set:
