        [1, 5, 1],
        [4, 2, 1]
    ]
    result = dijkstra(grid_sample)
    print(result)

def min_path_sum(grid):
    if not grid:
        return 0
    rows = len(grid)
    cols = len(grid[0])
    if rows == 1 and cols == 1:
        return grid[0][0]

    dp = [[0] * cols for _ in range(rows)]

    dp[0][0] = grid[0][0]

    for j in range(1, cols):
        dp[0][j] = dp[0][j - 1] + grid[0][j]

    for i in range(1, rows):
        dp[i][0] = dp[i - 1][0] + grid[i][0]

    for i in range(1, rows):
        for j in range(1, cols):
            dp[i][j] = min(dp[i - 1][j], dp[i][j - 1]) + grid[i][j]

    return dp[rows - 1][cols - 1]

if __name__ == '__main__':
    grid = [
        [1, 3, 1],
        [1, 5, 1],
        [4, 2, 1]
    ]
    result = min_path_sum(grid)
    print(result)

def shortest_path_grid(grid):
    m = len(grid)
    n = len(grid[0])

    if grid[0][0] == 1 or grid[m-1][n-1] == 1:
        return -1

    dp = [[-1] * n for _ in range(m)]
    dp[0][0] = 1

    for i in range(m):
        for j in range(n):
            if grid[i][j] == 1:
                dp[i][j] = -1
                continue

            if i > 0 and dp[i-1][j] != -1:
                if dp[i][j] == -1 or dp[i-1][j] < dp[i][j]:
                    dp[i][j] = dp[i-1][j] + 1

            if j > 0 and dp[i][j-1] != -1:
                if dp[i][j] == -1 or dp[i][j-1] < dp[i][j]:
                    dp[i][j] = dp[i][j-1] + 1

    return dp[m-1][n-1] if dp[m-1][n-1] != -1 else -1

if __name__ == '__main__':
